/// <summary>Facts about a Hebrew year.</summary>
public sealed class YearInfo
{
    /// <summary>The year, for example 5785.</summary>
    public int Year { get; }

    /// <summary>Whether it has 13 months.</summary>
    public bool IsLeap { get; }

    /// <summary>The number of days, 353 to 385.</summary>
    public int Days { get; }

    /// <summary>Whether Cheshvan and Kislev are long or short.</summary>
    public YearLength Length { get; }

    /// <summary>Whether Cheshvan has 30 days.</summary>
    public bool IsCheshvanLong { get; }

    /// <summary>Whether Kislev has 29 days.</summary>
    public bool IsKislevShort { get; }

    /// <summary>The months in order, from Tishrei.</summary>
    public HebrewMonth[] Months { get; }

    /// <summary>Creates a <see cref="YearInfo"/> from every field.</summary>
    public YearInfo(int year, bool isLeap, int days, YearLength length, bool isCheshvanLong, bool isKislevShort, HebrewMonth[] months)
    {
        Year = year;
        IsLeap = isLeap;
        Days = days;
        Length = length;
        IsCheshvanLong = isCheshvanLong;
        IsKislevShort = isKislevShort;
        Months = months;
    }

    internal void WriteTo(FfiBufferWriter writer)
    {
        writer.WriteI32(Year);
        writer.WriteBool(IsLeap);
        writer.WriteI32(Days);
        writer.WriteI32((int)Length);
        writer.WriteBool(IsCheshvanLong);
        writer.WriteBool(IsKislevShort);
        FfiCodecs.WriteListOfHebrewMonth(writer, Months);
    }

    internal static YearInfo ReadFrom(FfiBufferReader reader)
    {
        return new YearInfo(
            reader.ReadI32(),
            reader.ReadBool(),
            reader.ReadI32(),
            (global::KosherRustBindings.YearLength)reader.ReadI32(),
            reader.ReadBool(),
            reader.ReadBool(),
            FfiCodecs.ReadListOfHebrewMonth(reader));
    }
}

