{
    /// <summary>The NOAA algorithm, KosherJava's default. Good to about a minute.</summary>
    Noaa = 0,
    /// <summary>Jean Meeus's higher-accuracy VSOP87 algorithm.</summary>
    Meeus = 1,
    /// <summary>The NREL Solar Position Algorithm, solved on the topocentric zenith.</summary>
