    /// <summary>The time zone callback failed.</summary>
    TimeZoneCallbackFailed = 4,
    /// <summary>An internal calculation error.</summary>
    Internal = 5,
}

/// <summary>How `Zmanim` calculates. `default_config` matches KosherJava's defaults.</summary>
public sealed class Config
{
    /// <summary>How long before sea-level sunset candle lighting is, in minutes. Default 18.</summary>
    public int CandleLightingMinutes { get; }

    /// <summary>Whether proportional zmanim divide the day at astronomical *chatzos*. Default false.</summary>
    public bool UseAstronomicalChatzosForOtherZmanim { get; }

    /// <summary>
    /// Whether elevation adjusts every zman built on sunrise and sunset, not only sunrise
    /// and sunset themselves. Default false.
    /// </summary>
    public bool UseElevation { get; }

    /// <summary>How long after sunset Tzais Ateret Torah is, in minutes. Default 40.</summary>
    public int AteretTorahSunsetMinutes { get; }

    /// <summary>
    /// Whether *chatzos* is the sun's transit rather than the midpoint of sunrise and
    /// sunset. Default true.
    /// </summary>
    public bool UseAstronomicalChatzos { get; }

    /// <summary>The solar position algorithm. Default NOAA.</summary>
    public Calculator Calculator { get; }

    /// <summary>For Meeus and SPA: whether to apply the delta-T (TT - UT) correction. Default true.</summary>
    public bool ApplyDeltaT { get; }

