        UseAstronomicalChatzosForOtherZmanim = useAstronomicalChatzosForOtherZmanim;
        UseElevation = useElevation;
        AteretTorahSunsetMinutes = ateretTorahSunsetMinutes;
        UseAstronomicalChatzos = useAstronomicalChatzos;
        Calculator = calculator;
        ApplyDeltaT = applyDeltaT;
    }

    internal void WriteTo(FfiBufferWriter writer)
    {
        writer.WriteI32(CandleLightingMinutes);
        writer.WriteBool(UseAstronomicalChatzosForOtherZmanim);
        writer.WriteBool(UseElevation);
