/// <summary>The value-buffer codec of every composite type the API
/// carries.</summary>
internal static class FfiCodecs
{
    /// <summary>Reads one value that must fill the whole buffer.</summary>
    internal static T Decode<T>(FfiBufferReader reader, Func<FfiBufferReader, T> read)
    {
        var value = read(reader);
        reader.ExpectEnd();
        return value;
    }

    internal static void WriteListOfHebrewMonth(FfiBufferWriter writer, HebrewMonth[] value)
    {
        writer.WriteLen(value.Length);
        foreach (var item in value)
        {
            writer.WriteI32((int)item);
        }
    }

    internal static HebrewMonth[] ReadListOfHebrewMonth(FfiBufferReader reader)
    {
        var count = reader.ReadLen();
        var list = new List<HebrewMonth>(reader.Capacity(count));
        for (var i = 0; i < count; i++)
        {
            list.Add((global::KosherRustBindings.HebrewMonth)reader.ReadI32());
        }
        return list.ToArray();
    }

    internal static void WriteListOfHoliday(FfiBufferWriter writer, Holiday[] value)
    {
        writer.WriteLen(value.Length);
        foreach (var item in value)
        {
            item.WriteTo(writer);
        }
    }

    internal static Holiday[] ReadListOfHoliday(FfiBufferReader reader)
    {
        var count = reader.ReadLen();
        var list = new List<Holiday>(reader.Capacity(count));
        for (var i = 0; i < count; i++)
        {
            list.Add(global::KosherRustBindings.Holiday.ReadFrom(reader));
        }
        return list.ToArray();
    }

    internal static void WriteListOfMyZman(FfiBufferWriter writer, MyZman[] value)
    {
        writer.WriteLen(value.Length);
        foreach (var item in value)
        {
            writer.WriteI32((int)item);
        }
    }

    internal static MyZman[] ReadListOfMyZman(FfiBufferReader reader)
    {
        var count = reader.ReadLen();
        var list = new List<MyZman>(reader.Capacity(count));
